import * as T from'../vendor/three.module.js';
import{barkMaterial,groundPaint}from'../sunny/art-materials.js?v=2';
import{breeze}from'../sunny/plants.js?v=2';
import{GLTFLoader}from'../vendor/addons/loaders/GLTFLoader.js';
export const treeModels={'pine':'tree_pineTallA_detailed','spruce':'tree_pineTallB_detailed','fir':'tree_pineRoundB','birch':'tree_thin','broadleaf':'tree_detailed','pine-small':'tree_pineSmallA','juniper':'plant_bushLarge'};
const files=[...Object.values(treeModels),'tree_oak','tree_small','plant_bushDetailed','plant_bushSmall','grass','grass_large','grass_leafs','flower_purpleA','flower_purpleB','flower_yellowA','flower_yellowB','flower_redA','rock_largeA','rock_largeB','rock_smallA','rock_smallB','rock_tallC','bridge_wood','fence_planks','sign','campfire_stones'];
export class Assets{
 constructor(){this.loader=new GLTFLoader();this.models=new Map();this.templates=new Map();}
 async load(progress=()=>{}){let done=0;await Promise.all([...new Set(files),'character-male'].map(async name=>{const gltf=await this.loader.loadAsync(new URL('./assets/'+name+'.glb',import.meta.url).href);this.models.set(name,gltf);progress(++done/(files.length+1));}));}
 template(name){if(this.templates.has(name))return this.templates.get(name);const root=this.models.get(name)?.scene;if(!root)throw Error('模型未载入：'+name);root.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(root),size=bounds.getSize(new T.Vector3()),centre=bounds.getCenter(new T.Vector3()),parts=[];root.traverse(m=>{if(!m.isMesh)return;const geometry=m.geometry.clone().applyMatrix4(m.matrixWorld);geometry.translate(-centre.x,-bounds.min.y,-centre.z);let material=m.material;if(name.startsWith('tree_')){const original=Array.isArray(material)?material[0]:material;if(original.name?.toLowerCase().includes('wood')){material=barkMaterial(name==='tree_thin');const uv=[],p=geometry.attributes.position;for(let i=0;i<p.count;i++)uv.push(Math.atan2(p.getZ(i),p.getX(i))/(Math.PI*2)+.5,p.getY(i)*2.5);geometry.setAttribute('uv',new T.Float32BufferAttribute(uv,2));}else{material=groundPaint(original.clone());material.roughness=.98;breeze(material,.018);}}parts.push({geometry,material});});const value={parts,height:size.y,width:size.x,depth:size.z};this.templates.set(name,value);return value;}
 batch(name,capacity,{material=null,shadow=true}={}){const t=this.template(name),group=new T.Group(),meshes=t.parts.map(p=>{const mesh=new T.InstancedMesh(p.geometry,material||p.material,capacity);mesh.count=0;mesh.castShadow=shadow;mesh.receiveShadow=true;mesh.frustumCulled=false;group.add(mesh);return mesh;});return{group,meshes,capacity,height:t.height,set(rows){const dummy=new T.Object3D(),color=new T.Color();const count=Math.min(capacity,rows.length);for(let i=0;i<count;i++){const p=rows[i],s=p.height/t.height;dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(p.tiltX||0,p.angle||0,p.tiltZ||0);dummy.scale.set(s*(p.wide||1),s,s*(p.wide||1));dummy.updateMatrix();for(const mesh of meshes){mesh.setMatrixAt(i,dummy.matrix);if(p.color)mesh.setColorAt(i,color.set(p.color));}}for(const mesh of meshes){mesh.count=count;mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;}}};}
 avatar(){const gltf=this.models.get('character-male'),group=new T.Group(),pose=new T.Group(),model=gltf.scene,box=new T.Box3().setFromObject(model),size=box.getSize(new T.Vector3());model.scale.setScalar(1.75/size.y);model.position.y=-box.min.y*(1.75/size.y);model.traverse(m=>{if(m.isMesh){m.castShadow=true;m.receiveShadow=true;}});group.add(pose);pose.add(model);const mixer=new T.AnimationMixer(model),actions=new Map(gltf.animations.map(c=>[c.name,mixer.clipAction(c)]));let current=null;
  const bag=new T.Mesh(new T.BoxGeometry(.34,.43,.16),new T.MeshStandardMaterial({color:'#727d58',roughness:.96}));bag.position.set(0,1.12,-.25);bag.castShadow=true;group.add(bag);const roll=new T.Mesh(new T.CylinderGeometry(.08,.08,.42,10),new T.MeshStandardMaterial({color:'#c9baa0',roughness:1}));roll.rotation.z=Math.PI/2;roll.position.set(0,.9,-.26);group.add(roll);
  const fabric=new T.MeshStandardMaterial({color:'#b58760',roughness:.94}),scarf=new T.Mesh(new T.TorusGeometry(.11,.035,7,18),fabric);scarf.rotation.x=Math.PI/2;scarf.position.set(0,1.43,.005);pose.add(scarf);const end=new T.Mesh(new T.BoxGeometry(.11,.23,.025),fabric);end.position.set(.065,1.29,.17);end.rotation.z=-.17;pose.add(end);const straps=new T.MeshStandardMaterial({color:'#595f44',roughness:.98});for(const side of[-1,1]){const path=new T.CatmullRomCurve3([new T.Vector3(side*.14,.94,-.23),new T.Vector3(side*.17,1.4,-.12),new T.Vector3(side*.18,1.36,.13),new T.Vector3(side*.15,.98,.16)]),strap=new T.Mesh(new T.TubeGeometry(path,12,.023,5,false),straps);pose.add(strap);}pose.add(bag,roll);return{group,mixer,pose,animate(name){if(name===current)return;const next=actions.get(name)||actions.get('idle');if(!next)return;const prev=actions.get(current);next.reset().setEffectiveTimeScale(1).setEffectiveWeight(1).play();if(prev)prev.crossFadeTo(next,.18,false);current=name;},setMotion(state,dt){const boost=state.running&&state.moving,target=state.flying?(boost?.65:.12):state.riding?(boost?.4:.08):boost?.16:0;pose.rotation.x=T.MathUtils.lerp(pose.rotation.x,target,1-Math.exp(-dt*10));const action=actions.get(current);if(action)action.timeScale=state.moving?(boost?1.25:1):1;},update(dt){mixer.update(dt);}};
 }
}
